import { api } from '../core/api/client';
import { toast } from '../shared/toast';
import type { Agent, BrandingConfig } from '../core/types';
import { ProviderSetup } from '../setup/ProviderSetup';
import { IntegrationsTab } from './IntegrationsTab';
import { DataTab } from './DataTab';
import { LogsTab } from './LogsTab';
import { SecurityTab } from './SecurityTab';
import { NotificationSettings } from './NotificationSettings';
import { DeleteAgentModal } from './DeleteAgentModal';
import { AgentMark } from '../shared/AgentMark';

interface Props {
  branding: BrandingConfig | null;
  onBrandingUpdate: (b: BrandingConfig) => void;
  onClose: () => void;
}

type Tab = 'providers' | 'branding' | 'integrations' | 'chat' | 'language' | 'data' | 'logs' | 'security' | 'danger';

export function SettingsPanel({ branding, onBrandingUpdate, onClose }: Props) {
  const { t, i18n } = useTranslation();
  const clearCrmPhrase = t('settings.danger.clearCrmPhrase');
  const [tab, setTab] = useState<Tab>('providers');
  const [deleteAgent, setDeleteAgent] = useState<Agent | null>(null);
  const [dangerAgents, setDangerAgents] = useState<Agent[]>([]);
  const [crmConfirm, setCrmConfirm] = useState('');
  const [crmClearing, setCrmClearing] = useState(false);
  const [crmCleared, setCrmCleared] = useState(false);
  const [crmError, setCrmError] = useState('');

  useEffect(() => {
    if (tab === 'danger') {
      // best-effort: danger-zone list stays empty on failure
      api<{ agents: Agent[] }>('/api/agents').then(d => setDangerAgents(d.agents)).catch(() => {});
    }
  }, [tab]);
  const [companyName, setCompanyName] = useState(branding?.company_name || '');
  const [accentColor, setAccentColor] = useState(branding?.accent_color || '#C8D1D9');
  const [saving, setSaving] = useState(false);
  const [showToolCalls, setShowToolCalls] = useState(() =>
    localStorage.getItem('chatty_show_tool_calls') === 'true'
  );
  const [alwaysPowerMode, setAlwaysPowerMode] = useState(false);
  const [triageMode, setTriageMode] = useState<string>('always_cheap');
  const [defaultModelTier, setDefaultModelTier] = useState<string>('auto');
  const [tierLabels, setTierLabels] = useState<Record<string, string>>({});
  const [botReplyLimitEnabled, setBotReplyLimitEnabled] = useState(true);
  const [botReplyLimit, setBotReplyLimit] = useState(5);
  const [commitmentsEnabled, setCommitmentsEnabled] = useState(true);
  const [commitmentsDailyCap, setCommitmentsDailyCap] = useState(3);

  // Security settings
  const [securityExpanded, setSecurityExpanded] = useState(false);
  const [injectionScanning, setInjectionScanning] = useState<string>('flag');
  const [hbBudgetEnabled, setHbBudgetEnabled] = useState(true);
  const [hbBudget, setHbBudget] = useState(10);
  const [intBudgetEnabled, setIntBudgetEnabled] = useState(true);
  const [intBudget, setIntBudget] = useState(50);
  const [hourlyEnabled, setHourlyEnabled] = useState(false);
  const [hourlyLimit, setHourlyLimit] = useState(100);
  const [eventRetention, setEventRetention] = useState(90);

  useEffect(() => {
    if (tab === 'chat') {
      api<Record<string, unknown>>('/api/setup/admin-settings')
        .then(s => {
          setAlwaysPowerMode(s.always_power_mode as boolean);
          setTriageMode(s.triage_mode as string);
          setDefaultModelTier((s.default_model_tier as string) || 'auto');
          setInjectionScanning((s.injection_scanning as string) || 'flag');
          setHbBudgetEnabled(s.write_budget_heartbeat_enabled as boolean ?? true);
          setHbBudget(s.write_budget_heartbeat as number ?? 10);
          setIntBudgetEnabled(s.write_budget_interactive_enabled as boolean ?? true);
          setIntBudget(s.write_budget_interactive as number ?? 50);
          setHourlyEnabled(s.hourly_write_rate_limit_enabled as boolean ?? false);
          setHourlyLimit(s.hourly_write_rate_limit as number ?? 100);
          setEventRetention(s.event_log_retention_days as number ?? 90);
          setBotReplyLimitEnabled(s.bot_reply_limit_enabled as boolean ?? true);
          setBotReplyLimit(s.bot_reply_limit as number ?? 5);
          setCommitmentsEnabled(s.commitments_enabled as boolean ?? true);
          setCommitmentsDailyCap(s.commitments_daily_cap as number ?? 3);
        })
        .catch(() => {});
      api<{ tier_labels: Record<string, Record<string, string>>; active_provider: string }>('/api/providers/tiers')
        .then(d => setTierLabels(d.tier_labels?.[d.active_provider] || {}))
        .catch(() => {});
    }
  }, [tab]);

  async function saveBranding() {
    setSaving(true);
    try {
      const updated = await api<BrandingConfig>('/api/branding', {
        method: 'PUT',
        body: JSON.stringify({ company_name: companyName, accent_color: accentColor }),
      });
      onBrandingUpdate(updated);
      document.documentElement.style.setProperty('--brand-color', updated.accent_color);
    } catch {
      toast.error(t('settings.branding.saveFailed'));
    } finally {
      setSaving(false);
    }
  }

  async function uploadLogo(file: File) {
    const form = new FormData();
    form.append('file', file);
    const res = await fetch('/api/branding/logo', {
      method: 'POST',
      headers: { Authorization: `Bearer ${sessionStorage.getItem('chatty_token')}` },
      body: form,
    });
    if (!res.ok) throw new Error('Upload failed');
    onBrandingUpdate({ ...branding!, has_logo: true });
  }

  const tabs: { id: Tab; label: string }[] = [
    { id: 'providers', label: t('settings.tabs.providers') },
    { id: 'branding', label: t('settings.tabs.branding') },
    { id: 'integrations', label: t('settings.tabs.integrations') },
    { id: 'chat', label: t('settings.tabs.chat') },
    { id: 'language', label: t('settings.tabs.language') },
    { id: 'data', label: t('settings.tabs.data') },
    { id: 'logs', label: t('settings.tabs.logs') },
    { id: 'security', label: t('settings.tabs.security') },
    { id: 'danger', label: t('settings.tabs.danger') },
  ];

  return (
    <div onClick={onClose} style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)',
      display: 'flex', justifyContent: 'flex-end', zIndex: 50,
    }}>
      <div onClick={e => e.stopPropagation()} style={{
        background: '#11141A', borderLeft: '1px solid rgba(230,235,242,0.07)',
        width: '100%', maxWidth: 520, height: '100%',
        display: 'flex', flexDirection: 'column',
        boxShadow: '-8px 0 40px rgba(0,0,0,0.5)',
      }}>
        {/* Header */}
        <div style={{
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          padding: '0 24px', height: 48,
          borderBottom: '1px solid rgba(230,235,242,0.07)',
        }}>
          <h2 style={{
            fontFamily: "'Fraunces', Georgia, serif",
            fontSize: 16, fontWeight: 400, letterSpacing: '-0.01em',
            color: '#EDF0F4', margin: 0,
          }}>
            {t('settings.title')}
          </h2>

          <button onClick={onClose} style={{
            background: 'none',
            border: 'none',
            color: 'rgba(237,240,244,0.62)',
